"""Prix (slide 13) : 30 mises en page entièrement différentes (plus de flèche + 3 bulles). Pierre, 11 Nov 2026."""
H = r"""const tb=A.texts(sl).filter(t=>/^\$/.test(t.text)).sort((a,b)=>a.x-b.x);
const D=tb.map(t=>{const ps=[...t.el.querySelectorAll('p')].filter(p=>p.textContent.trim());const tx=p=>p.innerText.replace(/\s+/g,' ').trim();return {p:tx(ps[0]),d:ps.slice(1).map(tx).join(' ')}});
sl.querySelector('.raw').style.display='none';
const PK='#FB0161',CR='#E7CDA8',SL='#33525F',MU='#9FB0B7',G=['#4A6470','#B8325F','#FB0161'],LV=['Entry','Mid-range','Premium'];
const st=(html,css='')=>{const d=document.createElement('div');d.style.cssText='position:absolute;left:70px;top:180px;width:820px;height:390px;display:flex;align-items:center;justify-content:center;font-family:Lexend;color:#E7CDA8;'+css;d.innerHTML=html;sl.appendChild(d);return d};
const T=(s,css)=>`<div style="${css}">${s}</div>`;
"""
V = []
def v(name, desc, js): V.append(dict(name=name, desc=desc, js=H + js, css=''))

v("Règle graduée", "Une règle de $0 à $100+ avec les trois plages colorées dessus, à leur vraie place ; le texte sous chaque plage.",
r"""const seg=[[0,15],[15,60],[60,100]],W=780;st(`<div style="width:${W}px"><div style="position:relative;height:60px">${seg.map((s,i)=>`<div style="position:absolute;left:${s[0]/100*W}px;width:${(s[1]-s[0])/100*W-4}px;top:22px;height:14px;border-radius:7px;background:${G[i]}"></div><div style="position:absolute;left:${s[0]/100*W}px;width:${(s[1]-s[0])/100*W}px;top:0;text-align:center;font:700 11pt Lexend;color:#fff">${D[i].p}</div>`).join('')}${[0,15,60,100].map(x=>`<div style="position:absolute;left:${x/100*W-10}px;top:42px;width:20px;text-align:center;font:9px Lexend;color:${MU}">${x==100?'100+':x}</div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:26px">${D.map((d,i)=>`<div style='border-top:3px solid ${G[i]};padding-top:10px;font-size:8.5pt;line-height:1.5'>${d.d}</div>`).join('')}</div></div>`)""")
v("Échelle verticale", "Trois lignes empilées, le premium en haut : grand prix à gauche, texte à droite, filets fins entre les lignes.",
r"""st(`<div style="width:720px">${[2,1,0].map((i,k)=>`<div style="display:grid;grid-template-columns:170px 1fr;align-items:center;gap:28px;padding:18px 0;${k<2?'border-bottom:1px solid #1E4558':''}"><div style="font:700 ${20-k*2}pt Lexend;color:${['#fff','#fff',CR][k]}">${D[i].p}</div><div style="font-size:9.5pt;line-height:1.55">${D[i].d}</div></div>`).join('')}</div>`)""")
v("Tableau", "Un vrai tableau à trois lignes : gamme, prix, ce qu'on y trouve ; en-têtes crème espacés.",
r"""st(`<table style="width:760px;border-collapse:collapse;font-family:Lexend"><tr>${['RANGE','PRICE','WHAT YOU GET'].map(h=>`<th style="text-align:left;font:600 7.5pt Lexend;letter-spacing:.2em;color:${MU};padding:0 0 10px;border-bottom:1px solid #33525F">${h}</th>`).join('')}</tr>${D.map((d,i)=>`<tr><td style="padding:16px 0;border-bottom:1px solid #1E4558;font:600 10pt Lexend;color:${CR};width:130px">${LV[i]}</td><td style="font:700 13pt Lexend;color:#fff;width:130px;border-bottom:1px solid #1E4558">${d.p}</td><td style="font-size:9pt;line-height:1.5;border-bottom:1px solid #1E4558">${d.d}</td></tr>`).join('')}</table>`)""")
v("Trois grands chiffres", "Pas de cartes : trois très grands prix alignés, séparés par des filets verticaux, le texte dessous.",
r"""st(`<div style="display:grid;grid-template-columns:repeat(3,1fr);width:800px">${D.map((d,i)=>`<div style="padding:0 26px;${i?'border-left:1px solid #1E4558':''};text-align:center"><div style="font:700 34pt Lexend;color:#fff;line-height:1.1">${d.p}</div><div style="font:600 7pt Lexend;letter-spacing:.22em;color:${MU};margin:8px 0 14px">${LV[i].toUpperCase()}</div><div style="font-size:9pt;line-height:1.55">${d.d}</div></div>`).join('')}</div>`)""")
v("Liste numérotée éditoriale", "Comme un article : 01, 02, 03 en rose gras, le prix en titre, le texte dessous, en une colonne.",
r"""st(`<div style="width:640px">${D.map((d,i)=>`<div style="display:flex;gap:22px;padding:12px 0"><div style="font:700 22pt Lexend;color:${PK};line-height:1">0${i+1}</div><div><div style="font:700 13pt Lexend;color:#fff">${d.p} <span style="font:500 8pt Lexend;letter-spacing:.16em;color:${MU};margin-left:8px">${LV[i].toUpperCase()}</span></div><div style="font-size:9pt;line-height:1.55;margin-top:4px">${d.d}</div></div></div>`).join('')}</div>`)""")
v("Menu de restaurant", "Le prix à droite, le nom de la gamme à gauche, reliés par des pointillés ; la description en italique dessous.",
r"""st(`<div style="width:640px">${D.map((d,i)=>`<div style="padding:14px 0"><div style="display:flex;align-items:baseline;gap:10px"><span style="font:700 13pt Lexend;color:#fff">${LV[i]}</span><span style="flex:1;border-bottom:2px dotted #33525F;transform:translateY(-4px)"></span><span style="font:700 13pt Lexend;color:${CR}">${d.p}</span></div><div style="font-size:9pt;line-height:1.5;color:${MU};font-style:italic;margin-top:4px">${d.d}</div></div>`).join('')}</div>`)""")
v("Pyramide", "Trois étages : la base large pour l'entrée de gamme, le sommet étroit pour le premium ; le texte à droite de chaque étage.",
r"""st(`<div style="display:grid;grid-template-columns:320px 1fr;gap:30px;align-items:center;width:800px"><div>${[2,1,0].map((i,k)=>`<div style="margin:0 auto 6px;width:${120+k*100}px;height:62px;background:${G[i]};clip-path:polygon(${k?'12%':'50%'} 0,${k?'88%':'50%'} 0,100% 100%,0 100%);display:flex;align-items:flex-end;justify-content:center;padding-bottom:10px;font:700 11pt Lexend;color:#fff">${D[i].p}</div>`).join('')}</div><div>${[2,1,0].map(i=>`<div style="height:68px;display:flex;align-items:center;font-size:9pt;line-height:1.5">${D[i].d}</div>`).join('')}</div></div>`)""")
v("Titre fort + trois lignes", "À gauche, une phrase-titre « From $0 to $60+ a month » ; à droite, les trois gammes en lignes.",
r"""st(`<div style="display:grid;grid-template-columns:260px 1fr;gap:44px;align-items:center;width:800px"><div style="font:700 26pt Lexend;color:#fff;line-height:1.2">From $0<br>to $60+<div style="font:500 10pt Lexend;color:${MU};margin-top:10px">a month, per learner</div></div><div>${D.map((d,i)=>`<div style="padding:12px 0 12px 18px;border-left:3px solid ${G[i]};margin:8px 0"><div style="font:700 11pt Lexend;color:#fff">${d.p}</div><div style="font-size:9pt;line-height:1.5;margin-top:3px">${d.d}</div></div>`).join('')}</div></div>`)""")
v("Jauge en demi-cercle", "Un compteur en demi-cercle à trois secteurs (ardoise, framboise, rose) ; chaque gamme est expliquée sous le compteur.",
r"""const a=(p)=>{const t=Math.PI*(1-p);return [130+110*Math.cos(t),130-110*Math.sin(t)]};const arc=(p0,p1,c)=>{const [x0,y0]=a(p0),[x1,y1]=a(p1);return `<path d="M${x0} ${y0} A110 110 0 0 1 ${x1} ${y1}" stroke="${c}" stroke-width="26" fill="none"/>`};st(`<div style="text-align:center"><svg width="260" height="140" viewBox="0 0 260 140">${arc(0,.32,G[0])}${arc(.34,.65,G[1])}${arc(.67,1,G[2])}</svg><div style="display:grid;grid-template-columns:repeat(3,230px);gap:20px;margin-top:14px">${D.map((d,i)=>`<div><div style="font:700 12pt Lexend;color:#fff"><i style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${G[i]};margin-right:8px"></i>${d.p}</div><div style="font-size:8.5pt;line-height:1.5;margin-top:6px">${d.d}</div></div>`).join('')}</div></div>`)""")
v("Curseur", "Comme un curseur d'interface : une piste, trois crans ; sous chaque cran, le prix et le texte.",
r"""st(`<div style="width:760px"><div style="position:relative;height:30px;margin:0 60px"><div style="position:absolute;top:13px;left:0;right:0;height:4px;border-radius:2px;background:#1E4558"></div>${[0,50,100].map((x,i)=>`<div style="position:absolute;left:calc(${x}% - 12px);top:3px;width:24px;height:24px;border-radius:50%;background:#062A3C;border:4px solid ${G[i]};box-sizing:border-box"></div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:18px;text-align:center">${D.map(d=>`<div><div style="font:700 13pt Lexend;color:#fff">${d.p}</div><div style="font-size:8.5pt;line-height:1.5;margin-top:6px">${d.d}</div></div>`).join('')}</div></div>`)""")
v("Ticket de caisse", "Un ticket : lignes en police à chasse fixe, prix alignés à droite, ligne pointillée, et une phrase par gamme.",
r"""st(`<div style="width:460px;background:#0B3850;border-radius:6px;padding:22px 28px;font-family:'Courier New',monospace;color:${CR}"><div style="text-align:center;letter-spacing:.3em;font-size:9pt;color:${MU}">EDTECH · MONTHLY PRICE</div><div style="border-bottom:1px dashed #4A6470;margin:12px 0"></div>${D.map((d,i)=>`<div style="display:flex;justify-content:space-between;font-size:11pt;font-weight:700;color:#fff;margin-top:10px"><span>${LV[i].toUpperCase()}</span><span>${d.p}</span></div><div style="font-size:8pt;line-height:1.5;margin-top:3px">${d.d}</div>`).join('')}<div style="border-bottom:1px dashed #4A6470;margin:14px 0 0"></div></div>`)""")
v("Thermomètre vertical", "Un thermomètre à gauche, rempli de bas en haut ; trois repères à hauteur des trois gammes, le texte en face.",
r"""st(`<div style="display:grid;grid-template-columns:60px 1fr;gap:26px;width:640px;height:340px"><div style="position:relative;margin:0 auto;width:18px;height:330px;border-radius:9px;background:#1E4558;overflow:hidden"><div style="position:absolute;bottom:0;left:0;right:0;height:100%;background:linear-gradient(0deg,#4A6470,#B8325F 50%,#FB0161)"></div></div><div style="display:flex;flex-direction:column;justify-content:space-between">${[2,1,0].map(i=>`<div><div style="font:700 13pt Lexend;color:#fff">${D[i].p}</div><div style="font-size:9pt;line-height:1.5;margin-top:4px">${D[i].d}</div></div>`).join('')}</div></div>`)""")
v("Colonnes alignées en bas", "Trois colonnes qui partent de la même ligne de base et montent de plus en plus haut, prix en haut de chaque colonne, texte dessous.",
r"""st(`<div style="display:grid;grid-template-columns:repeat(3,220px);gap:30px;align-items:end">${D.map((d,i)=>`<div><div style="font:700 13pt Lexend;color:#fff;text-align:center;margin-bottom:8px">${d.p}</div><div style="height:${50+i*60}px;background:${G[i]};border-radius:8px 8px 0 0"></div><div style="border-top:2px solid #4A6470;padding-top:12px;font-size:8.5pt;line-height:1.5;text-align:center">${d.d}</div></div>`).join('')}</div>`)""")
v("Barre segmentée unique", "Une seule barre horizontale coupée en trois, de l'ardoise au rose, prix écrits dedans ; textes dessous.",
r"""st(`<div style="width:780px"><div style="display:flex;height:44px;border-radius:22px;overflow:hidden">${D.map((d,i)=>`<div style="flex:1;background:${G[i]};display:flex;align-items:center;justify-content:center;font:700 12pt Lexend;color:#fff;${i?'border-left:3px solid #062A3C':''}">${d.p}</div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:18px">${D.map(d=>T(d.d,'font-size:9pt;line-height:1.55;text-align:center')).join('')}</div></div>`)""")
v("Spectre de fond", "Une large bande en dégradé continu de l'ardoise au rose ; les prix sont posés dessus, les textes dessous.",
r"""st(`<div style="width:780px"><div style="height:60px;border-radius:12px;background:linear-gradient(90deg,#33525F,#9A2F5E 55%,#FB0161);display:grid;grid-template-columns:repeat(3,1fr);align-items:center;text-align:center;font:700 14pt Lexend;color:#fff">${D.map(d=>`<div>${d.p}</div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:18px">${D.map(d=>T(d.d,'font-size:9pt;line-height:1.55;text-align:center')).join('')}</div></div>`)""")
v("Bandes horizontales", "Trois bandes pleine largeur l'une sous l'autre (de plus en plus colorées) : libellé, prix, texte sur une ligne.",
r"""st(`<div style="width:800px">${D.map((d,i)=>`<div style="display:grid;grid-template-columns:110px 120px 1fr;gap:20px;align-items:center;padding:16px 22px;margin:8px 0;border-radius:10px;background:${['#0B3850','#2A2A4A','#3D2148'][i]}"><div style="font:600 7.5pt Lexend;letter-spacing:.2em;color:${MU}">${LV[i].toUpperCase()}</div><div style="font:700 14pt Lexend;color:#fff">${d.p}</div><div style="font-size:9pt;line-height:1.5">${d.d}</div></div>`).join('')}</div>`)""")
v("Prix dans le texte", "Trois phrases centrées, le prix en gros et en gras au début de chaque phrase : une lecture, sans graphique.",
r"""st(`<div style="width:700px;text-align:center">${D.map((d,i)=>`<p style="margin:16px 0;font-size:11pt;line-height:1.5"><b style="font:700 18pt Lexend;color:${['#fff','#fff','#fff'][i]};margin-right:10px">${d.p}</b>${d.d.charAt(0).toLowerCase()+d.d.slice(1)}</p>`).join('')}</div>`)""")
v("Deux colonnes : gammes / produits", "Colonne gauche en rose plein foncé dégradé (gammes), colonne droite les descriptions ; comme une grille tarifaire SaaS.",
r"""st(`<div style="display:grid;grid-template-columns:200px 1fr;width:740px;border-radius:12px;overflow:hidden;border:1px solid #1E4558">${D.map((d,i)=>`<div style="background:${['#1E4558','#3D2A50','#5C2350'][i]};padding:20px;font:700 14pt Lexend;color:#fff;${i<2?'border-bottom:1px solid #062A3C':''}">${d.p}<div style="font:600 7pt Lexend;letter-spacing:.2em;color:#C9D4D8;margin-top:4px">${LV[i].toUpperCase()}</div></div><div style="padding:20px 24px;font-size:9pt;line-height:1.55;display:flex;align-items:center;${i<2?'border-bottom:1px solid #1E4558':''}">${d.d}</div>`).join('')}</div>`)""")
v("Plans tarifaires (style SaaS)", "Trois colonnes de plan comme sur un site : nom du plan, gros prix « / month », texte ; la colonne du milieu mise en avant.",
r"""st(`<div style="display:grid;grid-template-columns:repeat(3,230px);gap:18px;align-items:stretch">${D.map((d,i)=>`<div style="background:#0B3850;border-radius:14px;padding:22px 20px;${i==1?'outline:2px solid #FB0161;transform:translateY(-8px)':''}"><div style="font:600 7.5pt Lexend;letter-spacing:.22em;color:${MU}">${LV[i].toUpperCase()}</div><div style="font:700 22pt Lexend;color:#fff;margin:8px 0 2px">${d.p}</div><div style="font-size:8pt;color:${MU};margin-bottom:12px">per month</div><div style="font-size:8.5pt;line-height:1.5;border-top:1px solid #1E4558;padding-top:12px">${d.d}</div></div>`).join('')}</div>`)""")
v("Axe logarithmique", "Un axe $1 → $10 → $100 (les prix montent vite) avec trois crochets qui couvrent chaque plage ; textes sous les crochets.",
r"""const W=780,xs=v=>Math.log10(Math.max(v,1))/2*W;const R=[[1,15],[15,60],[60,100]];st(`<div style="width:${W}px"><div style="position:relative;height:70px">${R.map((r,i)=>`<div style="position:absolute;left:${xs(r[0])}px;width:${xs(r[1])-xs(r[0])-4}px;top:6px;height:22px;border:3px solid ${G[i]};border-bottom:none;border-radius:6px 6px 0 0"></div><div style="position:absolute;left:${xs(r[0])}px;width:${xs(r[1])-xs(r[0])}px;top:-16px;text-align:center;font:700 11pt Lexend;color:#fff">${D[i].p}</div>`).join('')}<div style="position:absolute;top:44px;left:0;right:0;height:2px;background:#4A6470"></div>${[1,10,100].map(x=>`<div style="position:absolute;left:${xs(x)-14}px;top:52px;width:28px;text-align:center;font:9px Lexend;color:${MU}">$${x}</div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:14px">${D.map(d=>T(d.d,'font-size:8.5pt;line-height:1.5')).join('')}</div></div>`)""")
v("Chevrons de texte", "Minimaliste : les trois prix sur une ligne reliés par des chevrons «  ›  », libellés dessous, puis les trois textes.",
r"""st(`<div style="width:780px;text-align:center"><div style="display:flex;justify-content:center;align-items:center;gap:22px;font:700 24pt Lexend;color:#fff">${D.map((d,i)=>`<span>${d.p}</span>${i<2?`<span style="color:#4A6470;font-weight:300">›</span>`:''}`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:22px">${D.map((d,i)=>`<div><div style="font:600 7pt Lexend;letter-spacing:.22em;color:${MU};margin-bottom:8px">${LV[i].toUpperCase()}</div><div style="font-size:9pt;line-height:1.5">${d.d}</div></div>`).join('')}</div></div>`)""")
v("Libellés de rang à gauche", "Trois rangées : le niveau en grand texte vertical à gauche (ENTRY, MID, PREMIUM), prix et texte à droite.",
r"""st(`<div style="width:700px">${D.map((d,i)=>`<div style="display:grid;grid-template-columns:44px 1fr;gap:22px;align-items:stretch;margin:10px 0"><div style="background:${G[i]};border-radius:8px;writing-mode:vertical-rl;transform:rotate(180deg);display:flex;align-items:center;justify-content:center;font:700 7pt Lexend;letter-spacing:.2em;color:#fff">${['ENTRY','MID','PREMIUM'][i]}</div><div style="padding:8px 0"><div style="font:700 13pt Lexend;color:#fff">${d.p}</div><div style="font-size:9pt;line-height:1.5;margin-top:3px">${d.d}</div></div></div>`).join('')}</div>`)""")
v("Comparateur à cases", "Un mini tableau comparatif : trois colonnes de gammes, trois lignes (prix, type de produit, exemple) ; cases nettes.",
r"""const ty=['Study apps & teacher tools','AI tutors & course subscriptions','Live human tutoring'];st(`<div style="display:grid;grid-template-columns:120px repeat(3,1fr);width:780px;font-size:9pt;line-height:1.45">${['','ENTRY','MID-RANGE','PREMIUM'].map(h=>`<div style="padding:10px;font:600 7.5pt Lexend;letter-spacing:.2em;color:${MU};border-bottom:1px solid #33525F">${h}</div>`).join('')}<div style="padding:14px 10px;color:${MU};border-bottom:1px solid #1E4558">Price</div>${D.map(d=>`<div style="padding:14px 10px;font:700 13pt Lexend;color:#fff;border-bottom:1px solid #1E4558">${d.p}</div>`).join('')}<div style="padding:14px 10px;color:${MU};border-bottom:1px solid #1E4558">What</div>${ty.map(t=>`<div style="padding:14px 10px;border-bottom:1px solid #1E4558">${t}</div>`).join('')}<div style="padding:14px 10px;color:${MU}">In short</div>${D.map(d=>`<div style="padding:14px 10px;font-size:8pt;color:#C9D4D8">${d.d}</div>`).join('')}</div>`)""")
v("Fiche de prix centrale", "Une seule grande fiche centrée, les trois gammes à l'intérieur séparées par des filets, comme une carte de tarifs.",
r"""st(`<div style="width:560px;background:#0B3850;border-radius:16px;padding:10px 34px;box-shadow:0 10px 30px rgba(0,0,0,.35)">${D.map((d,i)=>`<div style="padding:16px 0;${i<2?'border-bottom:1px solid #1E4558':''}"><div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font:600 8pt Lexend;letter-spacing:.2em;color:${MU}">${LV[i].toUpperCase()}</span><span style="font:700 15pt Lexend;color:#fff">${d.p}</span></div><div style="font-size:8.5pt;line-height:1.5;margin-top:6px">${d.d}</div></div>`).join('')}</div>`)""")
v("Points de densité", "Sous chaque prix, une petite grille de points dont le nombre augmente (3, 9, 18) : la valeur grandit visuellement, en ordre.",
r"""st(`<div style="display:grid;grid-template-columns:repeat(3,230px);gap:30px;text-align:center">${D.map((d,i)=>`<div><div style="font:700 15pt Lexend;color:#fff">${d.p}</div><div style="display:grid;grid-template-columns:repeat(6,10px);gap:5px;justify-content:center;height:40px;align-content:center;margin:12px 0">${Array.from({length:18},(_,j)=>`<i style="width:10px;height:10px;border-radius:50%;background:${j<[3,9,18][i]?PK:'#1E4558'}"></i>`).join('')}</div><div style="font-size:8.5pt;line-height:1.5">${d.d}</div></div>`).join('')}</div>`)""")
v("Timeline d'abonnement", "Les gammes comme des étapes d'un parcours d'apprenant : point, prix, texte ; ligne verticale à gauche.",
r"""st(`<div style="position:relative;width:600px;padding-left:40px"><div style="position:absolute;left:11px;top:14px;bottom:14px;width:2px;background:#33525F"></div>${D.map((d,i)=>`<div style="position:relative;padding:12px 0"><i style="position:absolute;left:-36px;top:16px;width:16px;height:16px;border-radius:50%;background:${G[i]};box-shadow:0 0 0 5px #062A3C"></i><div style="font:700 13pt Lexend;color:#fff">${d.p}<span style="font:600 7.5pt Lexend;letter-spacing:.2em;color:${MU};margin-left:12px">${LV[i].toUpperCase()}</span></div><div style="font-size:9pt;line-height:1.5;margin-top:3px">${d.d}</div></div>`).join('')}</div>`)""")
v("Grand chiffre en filigrane", "Trois colonnes de texte simples ; derrière chacune, le prix en très grand dans un bleu à peine plus clair.",
r"""st(`<div style="display:grid;grid-template-columns:repeat(3,240px);gap:30px">${D.map((d,i)=>`<div style="position:relative;padding-top:70px"><div style="position:absolute;top:0;left:0;right:0;text-align:center;font:700 46pt Lexend;color:#0D3A52;line-height:1">${d.p}</div><div style="position:relative;text-align:center;font:700 12pt Lexend;color:#fff">${LV[i]}</div><div style="position:relative;text-align:center;font-size:8.5pt;line-height:1.5;margin-top:8px">${d.d}</div></div>`).join('')}</div>`)""")
v("Quadrillage de fond", "Une grille fine en fond, les trois gammes posées à des hauteurs régulières comme sur un graphique prix/valeur.",
r"""st(`<div style="position:relative;width:780px;height:330px;background-image:linear-gradient(#123F57 1px,transparent 1px),linear-gradient(90deg,#123F57 1px,transparent 1px);background-size:65px 55px;border-left:2px solid #4A6470;border-bottom:2px solid #4A6470">${D.map((d,i)=>`<div style="position:absolute;left:${30+i*250}px;bottom:${30+i*100}px;width:220px"><div style="display:flex;align-items:center;gap:10px"><i style="width:14px;height:14px;border-radius:50%;background:${G[i]}"></i><b style="font:700 12pt Lexend;color:#fff">${d.p}</b></div><div style="font-size:8pt;line-height:1.45;margin-top:4px;background:#062A3C">${d.d}</div></div>`).join('')}<div style="position:absolute;left:-8px;top:-22px;font:9px Lexend;color:${MU}">PRICE ↑</div></div>`)""")
v("Onglets", "Trois onglets côte à côte (ENTRY, MID-RANGE, PREMIUM) avec le prix, et un panneau commun qui donne les trois explications en colonnes.",
r"""st(`<div style="width:780px"><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px">${D.map((d,i)=>`<div style="background:${['#123F57','#2E2D50','#4A2650'][i]};border-radius:10px 10px 0 0;padding:12px;text-align:center"><div style="font:600 7pt Lexend;letter-spacing:.2em;color:#C9D4D8">${LV[i].toUpperCase()}</div><div style="font:700 15pt Lexend;color:#fff;margin-top:2px">${d.p}</div></div>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px">${D.map((d,i)=>`<div style="background:#0B3850;padding:16px;font-size:8.5pt;line-height:1.5;border-radius:0 0 10px 10px">${d.d}</div>`).join('')}</div></div>`)""")
v("Cercles concentriques", "Trois anneaux emboîtés (le premium englobe les autres) à gauche, avec une légende alignée à droite.",
r"""st(`<div style="display:grid;grid-template-columns:300px 1fr;gap:40px;align-items:center;width:800px"><svg width="300" height="300" viewBox="0 0 300 300">${[2,1,0].map((i,k)=>`<circle cx="150" cy="${150+k*35}" r="${140-k*35}" fill="${['#3D2148','#2A2A4A','#0E3D55'][k]}" stroke="${G[i]}" stroke-width="3"/>`).join('')}${[2,1,0].map((i,k)=>`<text x="150" y="${40+k*70}" text-anchor="middle" font-family="Lexend" font-weight="700" font-size="15" fill="#fff">${D[i].p}</text>`).join('')}</svg><div>${[2,1,0].map(i=>`<div style="padding:12px 0"><div style="font:700 11pt Lexend;color:#fff"><i style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${G[i]};margin-right:8px"></i>${LV[i]}</div><div style="font-size:9pt;line-height:1.5;margin-top:4px">${D[i].d}</div></div>`).join('')}</div></div>`)""")
assert len(V) == 30, len(V)
L = [chr(65 + i) if i < 26 else 'Z' + chr(65 + i - 26) for i in range(30)]
item = dict(id='Q', title="Prix : 30 mises en page entièrement différentes", what="Plus de flèche ni de trois bulles : chaque variante est une autre façon de montrer trois gammes de prix (règle, tableau, menu, pyramide, compteur, plans SaaS…).",
            scope=[13], shot=13, fam='Prix', clip=None, mine='A', why="La règle graduée place chaque gamme à sa vraie position sur une échelle de prix : c'est la seule qui montre aussi l'écart réel entre les gammes.")
for l, x in zip(L, V): item[l] = x
item['keys'] = L
ITEMS = [item]
